		checklistButton = button("Checklist", () ->
		{
			showingSkipped = false;
			choosingRoute = false;
			revealAnchor = "checklist";
			focusTarget = "search";
			redraw();
		});
		footerNavigation.add(checklistButton, BorderLayout.WEST);
		footerNavigation.add(accountButton, BorderLayout.EAST);
